    size_t full_path_len = dir_len + file_len + 1; // +1 for '/' or '\' and null terminator

    char *full_path = malloc(full_path_len + 1); // +1 for null terminator
    if (!full_path) {
        return strdup(""); // Allocation failed
    }

    // Use snprintf for safe string concatenation
    int written = snprintf(full_path, full_path_len + 1, "%s/%s", dir_path, filename);
