    }
    if (fseek(file_ptr, 0, SEEK_SET) != 0) {
        fclose(file_ptr);
        free(full_path);
        return strdup(""); // Error seeking back to beginning of file
    }

    // Allocate memory for file content
    char *content = malloc(file_size + 1); // +1 for null terminator
    if (!content) {
        fclose(file_ptr);
        free(full_path);
        return strdup(""); // Allocation failed
    }

    // Read file content
    size_t bytes_read = fread(content, 1, file_size, file_ptr);
    if (bytes_read != (size_t)file_size) {
        // Check for read error, not just EOF if file_size was 0
        if (ferror(file_ptr)) {
            fclose(file_ptr);
            free(full_path);
            free(content);
            return strdup(""); // Read error
        }
