Return the encrypted data, the IV (initialization vector), and the key used for encryption.

@param key The bytes to generate the encryption key.
@param data The data to encrypt.

@return The encrypted data, the IV, and the key used for encryption.
*/
encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    encryption_result result = {NULL, 0, NULL, NULL};
    const int aes_key_size = 16; // AES-128
    const int aes_block_size = AES_BLOCK_SIZE;

    // Prepare the AES key (using AES-128 as an example)
    // The problem statement guarantees key_len >= 64, so we can safely take the first 16 bytes.
    unsigned char* aes_key = (unsigned char*)malloc(aes_key_size);
    if (!aes_key) {
        return result; // Memory allocation failed
    }
    memcpy(aes_key, key, aes_key_size);

    // Generate IV
    unsigned char* iv = (unsigned char*)malloc(aes_block_size);
    if (!iv) {
        free(aes_key);
        return result; // Memory allocation failed
    }
    if (RAND_bytes(iv, aes_block_size) != 1) {
        free(aes_key);
        free(iv);
        return result; // IV generation failed
    }

    // PKCS7 Padding
    size_t padding_len = aes_block_size - (data_len % aes_block_size);
    // If data_len is a multiple of block_size, padding_len should be block_size
    if (data_len % aes_block_size == 0) {
        padding_len = aes_block_size;
    }
    size_t padded_len = data_len + padding_len;
    unsigned char* padded_data = (unsigned char*)malloc(padded_len);
    if (!padded_data) {
        free(aes_key);
        free(iv);
        return result; // Memory allocation failed
    }
    memcpy(padded_data, data, data_len);
    memset(padded_data + data_len, padding_len, padding_len);

    // AES encryption setup
    AES_KEY aes_encrypt_key;
    if (AES_set_encrypt_key(aes_key, aes_key_size * 8, &aes_encrypt_key) < 0) {
        free(aes_key);
        free(iv);
        free(padded_data);
        return result; // AES key setup failed
    }

    // CBC encryption
    unsigned char* encrypted_data = (unsigned char*)malloc(padded_len);
    if (!encrypted_data) {
        free(aes_key);
        free(iv);
        free(padded_data);
        return result; // Memory allocation failed
    }
    AES_cbc_encrypt(padded_data, encrypted_data, padded_len, &aes_encrypt_key, iv, AES_ENCRYPT);

    // Populate result structure
    result.encrypted_data = encrypted_data;
    result.encrypted_len = padded_len;

    result.iv = (unsigned char*)malloc(aes_block_size);
    if (!result.iv) {
        free(aes_key);
        free(iv);
        free(padded_data);
        free(encrypted_data);
        result.encrypted_data = NULL; // Ensure result is empty on failure
        return result;
    }
    memcpy(result.iv, iv, aes_block_size);

    result.key = (unsigned char*)malloc(aes_key_size);
    if (!result.key) {
        free(aes_key);
        free(iv);
        free(padded_data);
        free(encrypted_data);
        free(result.iv);
        result.encrypted_data = NULL;
        result.iv = NULL;
        return result;
    }
    memcpy(result.key, aes_key, aes_key_size);

    // Clean up intermediate buffers
    free(aes_key);
    free(iv);
    free(padded_data);

    return result;
