int is_safe_path_component(const char *component) {
    if (component == NULL || strlen(component) == 0) {
        return 0; // Empty or NULL component is not safe
    }
    if (strstr(component, "..") != NULL) {
        return 0; // Contains path traversal
    }
    if (component[0] == '/' || component[0] == '\\') {
        return 0; // Absolute path indicator
    }
    return 1;
}

