    if (!std::regex_match(dir_path, safe_chars_regex)) {
        return "";
    }

    // Prevent path traversal for relative paths
    if (dir_path.rfind("..", 0) == 0) {
        return "";
    }

    // Resolve to absolute path
    char resolved_path[PATH_MAX];
    if (realpath(dir_path.c_str(), resolved_path) == nullptr) {
        return "";
    }

