    std::array<char, 128> buffer;
    std::string result = "";

    FILE *pipe = popen(command.c_str(), "r");
    if (!pipe) {
        return "";
    }

    while (fgets(buffer.data(), buffer.size(), pipe) != nullptr) {
        result += buffer.data();
    }

    int exit_code = pclose(pipe);
    if (exit_code != 0) {
        return "";
    }

    return result;
}

