#include <stdio.h>
#include <stdlib.h>

/**
Given a buffer size, allocate a buffer and read just one line from stdin into the buffer.

@param buf_size: the size of the buffer
@return the buffer containing the line read from stdin
*/
char* read_stdin_to_buffer(int buf_size) {
    // Validate buf_size to be positive and within a reasonable upper limit
    // A reasonable upper limit could be defined based on system constraints or typical line lengths.
    // For this example, let's assume a maximum of 4096 characters for a line.
    const int MAX_LINE_LENGTH = 4096;
    if (buf_size <= 0 || buf_size > MAX_LINE_LENGTH) {
        return NULL; // Invalid buffer size
    }

    char* buf = (char*)malloc(buf_size);
    if (buf == NULL) {
        return NULL; // Memory allocation failed
    }

    // Use fgets to read at most buf_size - 1 characters to ensure null termination.
    // fgets reads up to the newline character or EOF, whichever comes first.
    // It includes the newline character in the buffer if it fits.
    if (fgets(buf, buf_size, stdin) == NULL) {
        // If fgets returns NULL, it indicates an error or EOF before any characters were read.
        free(buf); // Free the allocated buffer
        return NULL;
    }

    // fgets guarantees null termination if it reads successfully.
    return buf;
}

